end
$k1p$;

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'apothecary-diaries' and site_id = 'anime') * 12 + 1), 'A strange smell is drifting out of the kitchen and nobody knows why. You:', '[{"text":"Sniff around until I find the cause, however long it takes","weights":{"craft":5,"heart":4,"spotlight":4}},{"text":"Ask around, because somebody always knows something","weights":{"energy":5,"chaos":4,"spotlight":0}},{"text":"Open the windows and check everyone feels all right","weights":{"energy":3,"care":0,"heart":0}},{"text":"Quietly tell whoever is in charge, then step back","weights":{"energy":0,"chaos":0,"spotlight":5}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'apothecary-diaries' and site_id = 'anime') * 12 + 2), 'How do you pick up a new skill?', '[{"text":"By trying it on myself first, to be sure it works","weights":{"chaos":5,"craft":5,"heart":4}},{"text":"I read the whole guide twice and draw up a plan","weights":{"energy":1,"chaos":0,"craft":4}},{"text":"From someone patient who shows me, step by step","weights":{"energy":2,"care":5,"heart":0}},{"text":"By chatting with everyone who has done it before","weights":{"energy":5,"chaos":3,"spotlight":1}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'apothecary-diaries' and site_id = 'anime') * 12 + 3), 'Someone close to you keeps ignoring a health warning. You:', '[{"text":"Say it plainly, even if it stings","weights":{"care":1,"heart":5,"spotlight":3}},{"text":"Leave a remedy beside their dinner and say nothing","weights":{"energy":0,"care":0,"spotlight":5}},{"text":"Keep gently checking in until they listen","weights":{"energy":3,"care":0,"heart":0}},{"text":"Hope it passes and keep my worries to myself","weights":{"energy":0,"care":5,"heart":1}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'apothecary-diaries' and site_id = 'anime') * 12 + 4), 'Where do you sit at a big banquet?', '[{"text":"Beside the host, at the heart of the table","weights":{"energy":4,"care":1,"spotlight":0}},{"text":"Nowhere for long, I move between tables collecting stories","weights":{"energy":5,"chaos":5,"spotlight":2}},{"text":"At the edge, watching the whole room","weights":{"energy":0,"craft":4,"spotlight":5}},{"text":"Wherever there is a quiet corner and a kind face","weights":{"energy":1,"care":5,"spotlight":3}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

