insert into public.personality_profiles (group_id, member_name, member_slug, photo_url, axes, trait_lines, ord, active, site_id, character_id) values ((select id from public.groups where slug = 'apothecary-diaries' and site_id = 'anime'), 'Lishu', 'lishu', null, '{"energy":35,"chaos":50,"care":75,"craft":70,"heart":45,"spotlight":50}'::jsonb, array['You are the youngest of your circle, and people want to look after you.', 'People sometimes mistake your real troubles for fussiness.']::text[], 3, true, 'anime', (select id from public.characters where group_id = (select id from public.groups where slug = 'apothecary-diaries' and site_id = 'anime') and slug = 'lishu')) on conflict (group_id, member_slug) do update set member_name = excluded.member_name, photo_url = null, axes = excluded.axes, trait_lines = excluded.trait_lines, ord = excluded.ord, active = excluded.active, site_id = excluded.site_id, character_id = excluded.character_id where personality_profiles.site_id = 'anime';

