insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'black-clover' and site_id = 'anime') * 12 + 4), 'How do you deal with your own temper?', '[{"text":"It flares, I shout, and ten minutes later it is gone","weights":{"energy":5,"chaos":4,"heart":4}},{"text":"I bottle it up, and the power leaks out anyway","weights":{"energy":1,"care":5,"heart":1}},{"text":"I laugh and turn it into a dare","weights":{"chaos":5,"heart":3,"care":1}},{"text":"I cool down and look for a smarter way","weights":{"chaos":0,"craft":4,"energy":1}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

