insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'black-clover' and site_id = 'anime') * 12 + 6), 'Which part of a mission would you want to own?', '[{"text":"The flashy finish, with the biggest explosion","weights":{"energy":5,"chaos":4,"craft":4}},{"text":"Making sure the whole team gets home","weights":{"care":0,"heart":2,"spotlight":4}},{"text":"Telling the crew to go further than they think they can","weights":{"heart":5,"chaos":4,"care":0}},{"text":"The plan, worked out in advance","weights":{"craft":4,"chaos":0,"energy":1}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'black-clover' and site_id = 'anime') * 12 + 7), 'After a long day on duty, what do you want most?', '[{"text":"A giant meal and a loud table full of friends","weights":{"energy":5,"care":4,"chaos":3}},{"text":"A quiet corner and a long bath to myself","weights":{"energy":0,"care":4,"spotlight":5}},{"text":"A fast ride somewhere with a view and no rules","weights":{"chaos":5,"craft":4,"energy":3}},{"text":"One more round of training before bed","weights":{"craft":2,"heart":4,"energy":3}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

