insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'inuyasha' and site_id = 'anime') * 12 + 1), 'A mossy old well in the garden hums when you walk by. What do you do?', '[{"text":"Jump in before anyone can talk me out of it","weights":{"energy":5,"chaos":4,"heart":1}},{"text":"Check the rim, the rope and the lid before I touch anything","weights":{"energy":1,"chaos":0,"spotlight":4}},{"text":"Walk past with a raised eyebrow, since wells are not my business","weights":{"energy":0,"care":5,"heart":4}},{"text":"Peek in, grin, and drop a pebble to see what happens","weights":{"chaos":5,"craft":4,"energy":3}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'inuyasha' and site_id = 'anime') * 12 + 2), 'Someone picks a fight with you in the street. How do you answer?', '[{"text":"Loudly, and I do not back down an inch","weights":{"energy":5,"heart":4,"spotlight":0}},{"text":"With a joke so clever they forget why they were angry","weights":{"chaos":4,"craft":4,"care":4}},{"text":"I step in front of whoever they are really picking on","weights":{"energy":4,"care":0,"heart":1}},{"text":"I do not answer at all, and let my record speak","weights":{"energy":0,"care":5,"spotlight":2}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'inuyasha' and site_id = 'anime') * 12 + 3), 'Your travelling group needs someone to take a job. You volunteer to:', '[{"text":"Cook for everyone and keep spirits up","weights":{"energy":4,"care":0,"heart":0}},{"text":"Scout ahead on my own and report back","weights":{"energy":1,"chaos":1,"spotlight":4}},{"text":"Haggle with the villagers for food and a place to sleep","weights":{"chaos":4,"craft":4,"heart":2}},{"text":"Keep watch through the night so nobody else has to","weights":{"energy":0,"care":0,"spotlight":5}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'inuyasha' and site_id = 'anime') * 12 + 4), 'Pick your road trip snack:', '[{"text":"Instant ramen, hot, shared around the fire","weights":{"energy":4,"care":1,"craft":2}},{"text":"Sweets, as many as my pockets hold","weights":{"energy":5,"chaos":5,"spotlight":0}},{"text":"Plain rice and tea, the same as always","weights":{"chaos":0,"care":0,"spotlight":4}},{"text":"Nothing, I travel light and I do not snack","weights":{"energy":0,"care":5,"heart":4}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'inuyasha' and site_id = 'anime') * 12 + 5), 'You have a soft spot you would rather nobody noticed. What do you do with it?', '[{"text":"Hide it behind a scowl and hope no one pokes it","weights":{"energy":3,"heart":4,"care":3}},{"text":"Let it show, because feelings are meant to be shared","weights":{"care":0,"heart":0,"energy":4}},{"text":"Turn it into a joke before anyone can say a word","weights":{"chaos":5,"craft":3,"spotlight":1}},{"text":"Keep it so far inside that I almost forget it exists","weights":{"energy":0,"spotlight":3,"care":5}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'inuyasha' and site_id = 'anime') * 12 + 6), 'A friend is about to make a very bad bet. You:', '[{"text":"Tell them straight that it is a terrible idea","weights":{"heart":5,"energy":3,"chaos":1}},{"text":"Quietly pay for it, then say nothing about it","weights":{"energy":1,"care":0,"spotlight":5}},{"text":"Place a smaller, smarter bet beside theirs and see who wins","weights":{"chaos":4,"craft":4,"heart":1}},{"text":"Make them promise to be careful and then hug them","weights":{"care":0,"heart":0,"energy":4}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'inuyasha' and site_id = 'anime') * 12 + 7), 'Which sidekick would you bring along on a long trek?', '[{"text":"A fast loyal pet that grows huge when it counts","weights":{"energy":2,"chaos":2,"care":1}},{"text":"A talkative friend who never stops asking questions","weights":{"energy":5,"chaos":4,"care":4}},{"text":"A trusty weapon I have spent years mastering","weights":{"energy":1,"craft":2,"spotlight":3}},{"text":"No one. A strong person walks alone","weights":{"energy":0,"care":5,"heart":3}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'inuyasha' and site_id = 'anime') * 12 + 8), 'A village elder hands you a charm that can calm your temper. You:', '[{"text":"Wear it, grumbling the whole time","weights":{"energy":3,"heart":4,"chaos":2}},{"text":"Thank them and wear it properly, since I try to keep the peace","weights":{"care":0,"heart":0,"spotlight":3}},{"text":"Hand it to the person who really needs it, with a wink","weights":{"chaos":4,"craft":3,"care":4}},{"text":"Hand it back. I have never needed one","weights":{"energy":0,"care":5,"heart":4}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

