insert into public.personality_profiles (group_id, member_name, member_slug, photo_url, axes, trait_lines, ord, active, site_id, character_id) values ((select id from public.groups where slug = 'inuyasha' and site_id = 'anime'), 'Inuyasha', 'inuyasha', null, '{"energy":50,"chaos":70,"care":45,"craft":45,"heart":60,"spotlight":50}'::jsonb, array['You are proud and stubborn, and you rarely back down once you have decided.', 'Being on the outside of the crowd as a kid left its mark on you.', 'Under all that pride, you are far softer than you let anyone see.']::text[], 1, true, 'anime', (select id from public.characters where group_id = (select id from public.groups where slug = 'inuyasha' and site_id = 'anime') and slug = 'inuyasha')) on conflict (group_id, member_slug) do update set member_name = excluded.member_name, photo_url = null, axes = excluded.axes, trait_lines = excluded.trait_lines, ord = excluded.ord, active = excluded.active, site_id = excluded.site_id, character_id = excluded.character_id where personality_profiles.site_id = 'anime';

