  if exists (select 1 from public.personality_questions where ord between (select id from public.groups where slug = 'jujutsu-kaisen' and site_id = 'anime') * 12 + 1 and (select id from public.groups where slug = 'jujutsu-kaisen' and site_id = 'anime') * 12 + 12 and site_id <> 'anime') then raise exception 'personality: a question of another site sits in the band of jujutsu-kaisen'; end if;
end
