insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'kaguya-sama-love-is-war' and site_id = 'anime') * 12 + 1), 'A rival beats your score by one point. What do you do?', '[{"text":"Study three more hours and act like it did not bother me","weights":{"energy":2,"chaos":1,"craft":4}},{"text":"Cheer for them out loud, then challenge them to a game","weights":{"energy":5,"chaos":5,"care":4}},{"text":"Quietly find out which topics they know that I do not","weights":{"energy":0,"heart":4,"spotlight":5}},{"text":"Plan a clever comeback and keep a perfectly straight face","weights":{"chaos":0,"craft":4,"heart":1}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'kaguya-sama-love-is-war' and site_id = 'anime') * 12 + 2), 'The free period starts and the room is yours. You reach for:', '[{"text":"A board game, and everyone is playing whether they like it or not","weights":{"energy":5,"chaos":5,"care":4}},{"text":"A handheld console and a pair of headphones","weights":{"energy":0,"craft":4,"spotlight":5}},{"text":"The to-do list, then tea for the whole room","weights":{"energy":3,"care":0,"heart":4}},{"text":"A good seat, where I can look busy while I wait for someone else to speak first","weights":{"energy":1,"chaos":0,"spotlight":1}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'kaguya-sama-love-is-war' and site_id = 'anime') * 12 + 3), 'A friend asks you for love advice. You:', '[{"text":"Tell them plainly to go and say it already","weights":{"energy":3,"heart":5,"spotlight":0}},{"text":"Listen first, then ask what they actually want","weights":{"care":0,"heart":2,"spotlight":2}},{"text":"Start with my own good news and forget to ask about theirs","weights":{"energy":3,"chaos":4,"heart":0}},{"text":"Give a confident theory that is half guesswork","weights":{"energy":5,"chaos":5,"craft":1}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'kaguya-sama-love-is-war' and site_id = 'anime') * 12 + 4), 'Your phone dies at the worst moment. Your first thought:', '[{"text":"Fine, I have a pen, paper and an old-fashioned way to do this","weights":{"energy":1,"chaos":0,"craft":4}},{"text":"Borrow someone else''s before I miss anything","weights":{"energy":4,"chaos":3,"care":4}},{"text":"A quiet hour at last, I will notice more without it","weights":{"energy":0,"heart":4,"spotlight":5}},{"text":"Text everyone from a different device and make a joke of it","weights":{"energy":5,"chaos":4,"care":3}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'kaguya-sama-love-is-war' and site_id = 'anime') * 12 + 5), 'Photo day. Which look is yours?', '[{"text":"Neat and correct, not a thread out of place","weights":{"energy":2,"chaos":0,"craft":4}},{"text":"Trendy, with sharp details, nails and accessories","weights":{"energy":3,"chaos":3,"spotlight":2}},{"text":"Whatever I woke up in, hair flying, grin on","weights":{"energy":5,"chaos":5,"craft":1}},{"text":"Hoodie, headphones round my neck, look away","weights":{"energy":0,"chaos":3,"spotlight":5}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'kaguya-sama-love-is-war' and site_id = 'anime') * 12 + 6), 'Someone you secretly like walks in. You:', '[{"text":"Act as if I do not care, and wait for them to make the first move","weights":{"energy":1,"chaos":0,"heart":0}},{"text":"Walk over calmly while my heart pounds under a steady face","weights":{"energy":2,"chaos":1,"heart":3}},{"text":"Wave, shout their name and ask what is for lunch","weights":{"energy":5,"chaos":5,"care":4}},{"text":"Watch from across the room and see everything","weights":{"energy":0,"spotlight":5}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

