insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'oshi-no-ko' and site_id = 'anime') * 12 + 1), 'Your school is putting on a talent show next month. What is your move?', '[{"text":"Sign up first and worry about the stage later","weights":{"energy":5,"spotlight":0,"craft":0}},{"text":"Watch other acts, take notes, and write a detailed plan","weights":{"craft":5,"energy":1,"chaos":0}},{"text":"Run the sign-up table and make sure every act gets a slot","weights":{"care":0,"heart":4,"spotlight":5}},{"text":"Find the shy friend with a hidden talent and talk them into it","weights":{"energy":3,"craft":4,"heart":4}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

